import argparse
import hashlib
import json
from pathlib import Path
import sqlite3

import categories
import config
import database
import models
import training_verification


def _database_path(connection):
    """Return the main SQLite file path, leaving separate in-memory databases distinct."""
    row = connection.execute('PRAGMA database_list').fetchone()
    return Path(row[2]).resolve() if row[2] else None


def _approved_labels(approvals):
    """Validate each explicit course approval without taking labels from private source columns."""
    training_verification._approved_patterns(approvals)
    result = {}
    for approval in approvals:
        title = approval['public_title'].strip()
        qualifier = (approval['appointment_description'] or '').strip()
        result[approval['external_id']] = (title, qualifier)
    return result


def _public_courses(connection, labels, taxonomy):
    """Read local identities and category keys, replacing every unreviewed course label."""
    allowed = {row['key'] for row in taxonomy['bundles']}
    rows = connection.execute('''SELECT s.id,s.external_id,b.key AS bundle_key
        FROM series s JOIN bundles b ON b.id=s.bundle_id
        WHERE s.source=? AND substr(s.external_id,1,?)=? ORDER BY s.id''',
        ('unisport', len(config.HISTORY_PATTERN_PREFIX), config.HISTORY_PATTERN_PREFIX)).fetchall()
    courses, masked = [], 0
    for row in rows:
        if row['id'] <= 0 or row['bundle_key'] not in allowed:
            raise ValueError('Source courses need valid identities and frozen category keys.')
        approved = labels.get(row['external_id'])
        title, sport = config.UNREVIEWED_ACTIVITY_TITLE, ''
        if approved is None:
            masked += 1
        else:
            sport, qualifier = approved
            title = sport + (' · ' + qualifier if qualifier else '')
        courses.append((row['id'], 'unisport', row['external_id'], title,
                        config.TRAINING_CATALOGUE_DESCRIPTION, 'Unisport HSG', row['bundle_key'],
                        sport, '', '', 'tba', config.UNISPORT_PUBLIC_SCHEDULE_URL,
                        '', None, 0, 1, 0))
    return courses, masked


def _public_occurrences(connection, courses, labels):
    """Copy dated slots and validated provenance without loading archive rows or personal fields."""
    course_ids = {course[0] for course in courses}
    rows = connection.execute('''SELECT e.id,e.series_id,e.start_time,e.end_time,
        e.end_is_estimated,e.status,s.external_id,p.kind,p.forecast_anchor_date,
        p.evidence_weeks,p.created_at,p.verification_url,p.verified_at
        FROM events e JOIN series s ON s.id=e.series_id
        LEFT JOIN event_provenance p ON p.event_id=e.id
        WHERE s.source=? AND substr(s.external_id,1,?)=? ORDER BY e.id''',
        ('unisport', len(config.HISTORY_PATTERN_PREFIX), config.HISTORY_PATTERN_PREFIX)).fetchall()
    if not rows or len(rows) > config.MAX_CATALOGUE_EVENTS:
        raise ValueError('The reviewed catalogue must contain a bounded, nonempty set of events.')
    events, proofs = [], []
    for row in rows:
        _validate_occurrence(row, course_ids, labels)
        events.append((row['id'], row['series_id'], row['start_time'], row['end_time'],
                       row['end_is_estimated'], row['status']))
        proofs.append((row['id'], row['kind'], row['forecast_anchor_date'], row['evidence_weeks'],
                       row['created_at'], row['verification_url'], row['verified_at']))
    return events, proofs


def _validate_occurrence(row, course_ids, labels):
    """Require explicit training evidence and preserve unknown availability rather than guessing."""
    if (row['id'] <= 0 or row['series_id'] not in course_ids or row['status'] != 'unknown'
            or row['end_is_estimated'] not in (0, 1)
            or row['kind'] not in ('projected', 'website')):
        raise ValueError('Runtime events require reviewed identities and unknown availability.')
    start, end = database.from_db_text(row['start_time']), database.from_db_text(row['end_time'])
    created = database.from_db_text(row['created_at'])
    if (database.to_db_text(start) != row['start_time']
            or database.to_db_text(end) != row['end_time']
            or database.to_db_text(created) != row['created_at']):
        raise ValueError('Runtime timestamps must use the canonical local time format.')
    models.Event(row['id'], row['series_id'], config.UNREVIEWED_ACTIVITY_TITLE, start, end,
                 '', 'tba', 'sports', '', '', provenance_kind=row['kind'],
                 forecast_anchor_date=row['forecast_anchor_date'],
                 evidence_weeks=row['evidence_weeks'],
                 verification_url=row['verification_url'], verified_at=row['verified_at'])
    if row['kind'] == 'website':
        if row['external_id'] not in labels:
            raise ValueError('Website events require an explicitly approved public course label.')
        first, last = training_verification._source_range(row['verification_url'])
        if not first <= start.date() <= last:
            raise ValueError('The website evidence does not cover the event date.')


def _catalogue_id(courses, events, proofs, taxonomy):
    """Fingerprint selected runtime content, not private historical data or original file names."""
    content = [taxonomy['_meta']['version'], courses, events, proofs]
    encoded = json.dumps(content, ensure_ascii=False, separators=(',', ':')).encode('utf-8')
    return 'reviewed-' + hashlib.sha256(encoded).hexdigest()


def _prepare_target(connection, catalogue_id):
    """Refuse a different existing dataset and identify safe same-content replays."""
    tables = connection.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
    if not tables:
        database.init_db(connection)
    else:
        names = {row['name'] for row in tables}
        required = {'app_settings', 'events', 'series', 'training_imports', 'training_history'}
        if not required <= names:
            raise ValueError('The target is not an empty WeekWise application database.')
    archived = connection.execute('''SELECT
        (SELECT COUNT(*) FROM training_history) +
        (SELECT COUNT(*) FROM training_imports) AS total''').fetchone()['total']
    if archived:
        raise ValueError('A private training archive must never be used as the runtime target.')
    existing_id = database.get_setting(connection, 'catalogue_id')
    if existing_id is not None:
        if (existing_id == catalogue_id and database.get_setting(
                connection, 'catalogue_mode') == config.REVIEWED_CATALOGUE_MODE):
            return False
        raise ValueError('The target contains a different catalogue; use a fresh output file.')
    occupied = connection.execute('''SELECT
        (SELECT COUNT(*) FROM series) + (SELECT COUNT(*) FROM events) +
        (SELECT COUNT(*) FROM users) + (SELECT COUNT(*) FROM clubs) +
        (SELECT COUNT(*) FROM interactions) + (SELECT COUNT(*) FROM invitations) +
        (SELECT COUNT(*) FROM favorites) + (SELECT COUNT(*) FROM import_log) AS total
        ''').fetchone()['total']
    if occupied:
        raise ValueError('The runtime target must be empty; existing data will not be replaced.')
    return True


def _insert_courses(connection, courses):
    """Map stable public bundle keys to local foreign keys inside the catalogue transaction."""
    bundle_ids = {}
    for row in connection.execute('SELECT id,key FROM bundles').fetchall():
        bundle_ids[row['key']] = row['id']
    for course in courses:
        values = course[:6] + (bundle_ids[course[6]],) + course[7:]
        connection.execute('''INSERT INTO series
            (id,source,external_id,title,description,organizer,bundle_id,sport,level,location,
             location_type,source_url,registration_url,price_rappen,members_only,
             is_recurring,is_placeholder) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''', values)


def build_training_catalogue(source_connection, target_connection, approvals):
    """Build a separate runtime catalogue from selected fields without modifying the archive.

    :param source_connection: private, initialized forecast database without pending writes
    :param target_connection: empty app database or a replay of this exact catalogue
    :param approvals: reviewed public product labels and appointment qualifiers from Task 5
    :return: aggregate row counts and a stable catalogue identity
    """
    if source_connection.in_transaction or target_connection.in_transaction:
        raise ValueError('Finish caller transactions before preparing an app catalogue.')
    source_path, target_path = _database_path(source_connection), _database_path(target_connection)
    if source_connection is target_connection or (source_path and source_path == target_path):
        raise ValueError('The runtime catalogue must be separate from its private source.')
    taxonomy = categories.load_taxonomy()
    labels = _approved_labels(approvals)
    courses, masked = _public_courses(source_connection, labels, taxonomy)
    events, proofs = _public_occurrences(source_connection, courses, labels)
    catalogue_id = _catalogue_id(courses, events, proofs, taxonomy)
    create = _prepare_target(target_connection, catalogue_id)
    if create:
        categories.seed_categories(target_connection, taxonomy)
        # Course: A07 – the selected courses, occurrences, provenance and marker commit together.
        with target_connection:
            _insert_courses(target_connection, courses)
            target_connection.executemany('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status) VALUES (?,?,?,?,?,?)''',
                events)
            target_connection.executemany('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,
                 verification_url,verified_at) VALUES (?,?,?,?,?,?,?)''', proofs)
            settings = (('catalogue_id', catalogue_id),
                        ('catalogue_mode', config.REVIEWED_CATALOGUE_MODE), ('setup_done', '1'))
            for key, value in settings:
                target_connection.execute('INSERT INTO app_settings (key,value) VALUES (?,?)',
                                            (key, value))
    return {'n_series': len(courses), 'n_events': len(events), 'n_masked_series': masked,
            'n_created': len(events) if create else 0, 'n_existing': 0 if create else len(events),
            'catalogue_id': catalogue_id}


def main():
    """Prepare a private local preview without network access or publication."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=config.TRAINING_HISTORY_DB)
    parser.add_argument('--review', type=Path, default=config.TRAINING_REVIEW_FILE)
    parser.add_argument('--output', type=Path, default=config.TRAINING_APP_DB)
    options = parser.parse_args()
    if not options.source.is_file():
        parser.exit(1, 'The private forecast source does not exist.\n')
    if (options.source.resolve() == options.output.resolve()
            or options.output.resolve() == config.TRAINING_HISTORY_DB.resolve()):
        parser.exit(1, 'Choose a separate runtime output database, never the private archive.\n')
    source, target = None, None
    try:
        if options.review.stat().st_size > config.MAX_TRAINING_VERIFICATION_BYTES:
            raise ValueError('The reviewed evidence file is too large.')
        package = json.loads(options.review.read_bytes())
        if not isinstance(package, dict):
            raise ValueError('The reviewed evidence file must be an object.')
        source = database.get_connection(options.source.resolve().as_uri() + '?mode=ro', uri=True)
        target = database.get_connection(options.output)
        report = build_training_catalogue(source, target, package.get('course_approvals'))
    except (OSError, sqlite3.Error, UnicodeError, ValueError):
        parser.exit(1, 'Could not prepare the catalogue; source and existing data retained.\n')
    finally:
        if source is not None:
            source.close()
        if target is not None:
            target.close()
    print(json.dumps(report, sort_keys=True))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
